## 6️⃣ TL;DR code snippet (copy-paste)

```kotlin
// ---- 1. Your decryption helper (you must implement) ----
object Vault {
    fun decryptTile(url: String): ByteArray? {
        // Example: parse "vault://tiles/12/3456/7890"
        val parts = url.removePrefix("vault://tiles/").split('/')
        if (parts.size != 3) return null
        val (z, x, y) = parts.map { it.toInt() }
        // … decrypt from your encrypted blob …
        return MyEncryptedBlob.getMvt(z, x, y)   // returns ByteArray?
    }
}

// ---- 2. Custom HttpRequest wrapper ----
class VaultHttpRequest(private val stock: HttpRequest) : HttpRequest {
    override fun executeRequest(
        responder: HttpResponder,
        nativePtr: Long,
        resourceUrl: String,
        dataRange: String?,
        etag: String?,
        modified: String?,
        offlineUsage: Boolean
    ) {
        if (!resourceUrl.startsWith("vault://")) {
            return stock.executeRequest(
                responder, nativePtr, resourceUrl,
                dataRange, etag, modified, offlineUsage
            )
        }

        val bytes = Vault.decryptTile(resourceUrl)
            ?: run {
                responder.handleFailure(HttpRequest.CONNECTION_ERROR, "Decrypt failed")
                return
            }

        responder.onResponse(200, null, null, null, null, null, null, bytes)
    }

    override fun cancelRequest() = stock.cancelRequest()
}

// ---- 3. Install the provider (e.g., in Application.onCreate) ----
class MyApp : Application() {
    override fun onCreate() {
        super.onCreate()
        val stock = MapLibre.getModuleProvider()
        MapLibre.setModuleProvider(object : ModuleProvider by stock {
            override fun createHttpRequest(): HttpRequest = VaultHttpRequest(stock.createHttpRequest())
        })
    }
}
```

Now you can keep your style exactly as you would on the web:

