### TL;DR code snippet (minimal)

```kotlin
mapLibreMap.getStyle { style ->
    // DEM source
    style.addSource(RasterDemSource("dem", "https://example.com/terrain.json"))

    // Visual relief (hillshade)
    style.addLayerBelow(
        HillshadeLayer("hillshade", "dem")
            .withProperties(
                hillshadeExaggeration(1.0f),
                hillshadeIlluminationDirection(315f),
                hillshadeIlluminationAnchor("map")
            ),
        "water"   // put it just above the water layer (choose any existing layer id)
    )
}
```

That is the **closest native equivalent** to the GL JS `setTerrain` call you posted. When MapLibre Native eventually ships true 3-D terrain, you’ll be able to replace the hillshade/color-relief block with a `Terrain` object and an `exaggeration` value, but until then the above is the recommended approach.

Below is a **complete, copy-and-paste-ready TypeScript example** that

1. **Creates an IndexedDB store** for vector-tile blobs (using the tiny `idb-keyval` helper – you can replace it with any IndexedDB wrapper you like).  
2. **Registers a custom `cache://` protocol** with MapLibre GL JS (`maplibregl.addProtocol`).  
3. **Falls back to the network** when a tile is not yet cached, writes the fetched tile into the DB, and returns the data to the renderer.  
4. **Initialises the map** with a style that points at `cache://tiles/{z}/{x}/{y}.pbf`.

> **What you need**  
> * MapLibre GL JS ≥ 4.0 (the promise-based `addProtocol` API).  
> * A bundler that can handle ES-modules (e.g. Vite, Webpack, Parcel) – the code works in a plain `<script type="module">` page as well.  
> * The `idb-keyval` package (≈ 1 KB) – you can also write the IndexedDB code yourself.

---

## 1️⃣ Install the tiny IndexedDB helper

```bash
npm i maplibre-gl idb-keyval
# or, if you use Yarn / pnpm
# yarn add maplibre-gl idb-keyval
```

---

## 2️⃣ TypeScript – `cache-protocol.ts`

```ts
// ---------------------------------------------------------------
//  cache-protocol.ts
// ---------------------------------------------------------------

import { addProtocol, ResourceResponse } from 'maplibre-gl';
import { get, set } from 'idb-keyval';

/**
 * The key we store each tile under.
 * We keep the same pattern that appears in the URL, e.g.
 *   cache://tiles/12/3456/7890.pbf
 * →  "tiles/12/3456/7890.pbf"
 */
function dbKeyFromUrl(url: string): string {
  // Strip the scheme and leading slash
  // url is something like "cache://tiles/12/3456/7890.pbf"
  return url.replace(/^cache:\/\//, '');
}

/**
 * Fetch a tile from the network (fallback when it is not cached).
 * You can replace this with any fetch logic you need (auth headers,
 * custom base URL, etc.).
 */
async function fetchTileFromNetwork(url: string): Promise<ArrayBuffer> {
  // The URL we actually request – replace the scheme with a real one.
  // In this example we assume the same path exists on a regular HTTP server.
  const httpUrl = url.replace(/^cache:\/\//, 'https://my.tileserver.com/');
  const resp = await fetch(httpUrl);
  if (!resp.ok) {
    throw new Error(`Network tile fetch failed: ${resp.status}`);
  }
  return await resp.arrayBuffer();
}

/**
 * Register the `cache://` protocol.
 *
 * The handler receives:
 *   - params: { url: string; request: Request; }
 *   - abortController: AbortController (optional, for cancellation)
 *
 * It must return a Promise that resolves to a ResourceResponse:
 *   {
 *     data: Uint8Array,
 *     cacheControl?: string,
 *     expires?: string,
 *     etag?: string,
 *     modified?: string,
 *     responseHeaders?: Record<string, string>
 *   }
 */
export function registerCacheProtocol(): void {
  addProtocol('cache', async (params, abortController) => {
    const { url } = params; // e.g. "cache://tiles/12/3456/7890.pbf"
    const key = dbKeyFromUrl(url);

    // 1️⃣ Try to read from IndexedDB
    const cached = await get<ArrayBuffer>(key);
    if (cached) {
      // Tile is already cached – return it immediately.
      return {
        data: new Uint8Array(cached),
        // Optional: you can add any HTTP-like metadata you like.
        // MapLibre does not require them, but they are useful for debugging.
        cacheControl: 'max-age=31536000',
      };
    }

    // 2️⃣ Not in the DB → fetch from the network.
    // Abort handling: if the request is cancelled, abort the fetch.
    const abortSignal = abortController?.signal;
    const networkPromise = fetchTileFromNetwork(url);

    // If the caller aborts, we forward the signal to the fetch.
    if (abortSignal) {
      abortSignal.addEventListener('abort', () => {
        // fetch() respects AbortSignal automatically, so nothing else needed.
      });
    }

    const arrayBuffer = await networkPromise;

    // 3️⃣ Store the freshly-fetched tile for next time.
    // We store the raw ArrayBuffer; idb-keyval will handle the conversion.
    await set(key, arrayBuffer);

    // 4️⃣ Return the tile to MapLibre.
    return {
      data: new Uint8Array(arrayBuffer),
      // You could also forward real HTTP headers if you have them.
    };
  });
}
```

