## 3️⃣ The map entry point – `main.ts`

```ts
// ---------------------------------------------------------------
//  main.ts
// ---------------------------------------------------------------

import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { registerCacheProtocol } from './cache-protocol';

// 1️⃣ Register the protocol **before** you create the map.
registerCacheProtocol();

// 2️⃣ Initialise the map.  The style can be an inline JSON object
//    or a URL that references the custom scheme.
const map = new maplibregl.Map({
  container: 'map',               // <div id="map"></div> in your HTML
  style: {
    version: 8,
    sources: {
      // The source points at the custom scheme.
      // The `{z}/{x}/{y}` placeholders are filled in by the renderer.
      // The ".pbf" suffix is optional – MapLibre will request exactly what you write.
      myTiles: {
        type: 'vector',
        tiles: ['cache://tiles/{z}/{x}/{y}.pbf'],
        // Optional: set a maxzoom that matches your source.
        maxzoom: 14,
      },
    },
    layers: [
      {
        id: 'my-fill',
        type: 'fill',
        source: 'myTiles',
        'source-layer': 'my_layer_name', // <-- change to the layer name inside the MVT
        paint: {
          'fill-color': '#3bb2d0',
          'fill-opacity': 0.6,
        },
      },
    ],
  },
  center: [0, 0],
  zoom: 2,
});
```

