## 7️⃣ TL;DR – the one-liner you can drop into any project

```ts
import { addProtocol } from 'maplibre-gl';
import { get, set } from 'idb-keyval';

addProtocol('cache', async ({ url }, abort) => {
  const key = url.replace(/^cache:\/\//, '');
  const cached = await get<ArrayBuffer>(key);
  if (cached) return { data: new Uint8Array(cached) };

  const httpUrl = url.replace(/^cache:\/\//, 'https://my.tileserver.com/');
  const resp = await fetch(httpUrl, { signal: abort?.signal });
  if (!resp.ok) throw new Error(`Tile fetch ${resp.status}`);
  const buf = await resp.arrayBuffer();
  await set(key, buf);
  return { data: new Uint8Array(buf) };
});
```

Place that **before** you create the `maplibregl.Map` instance, and reference `cache://…` in any vector-tile source. 🎉

